function UITalentMaterialLevelSelectionDialog:__init() 
    self._allBuffIds = {}             --所有可选的buff
    self._curChooseBuffId = 0           --当前选择的buff
    self._curQuestId = 0              --关卡buff
end

function UITalentMaterialLevelSelectionDialog:__delete()
    self._allBuffIds = nil             --所有可选的buff
    self._curChooseBuffId = nil          --当前选择的buff
    self._curQuestId = nil             --关卡buff
end

function UITalentMaterialLevelSelectionDialog:Awake()
    --SetButtonAction(self.BtnClose, Bind(self, self.OnBtnClose))

    local argument = self.controller.Argument.parameters
    if not argument then
        return
    end
    local t = argument.buffIds    
    self._curQuestId = checkNumber(argument.questId)

    if not t or checkNumber(self._curQuestId) == 0 then
        return
    end
    self._allBuffIds = {}
    for k, v in pairs(t) do
        table.insert(self._allBuffIds, v)
    end

    self:FillBuffs()
end

function UITalentMaterialLevelSelectionDialog:OnShow()
    ---@type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        --[[
        cs_coroutine.start(function()
            coroutine.yield(WaitForSeconds(2))
            local rootGo = self.controller.gameObject.transform:Find("Root")
            if not rootGo then
                return
            end
            rootGo:GetComponent(typeof(UIEffectCapturedImage)):Capture()
        end)
        ]]
    end))
    return coWait
end

function UITalentMaterialLevelSelectionDialog:FillBuffs()
    for k, v in pairs(self._allBuffIds) do
        local vo = QuestConfMgr:GetInstance():GetTalentBuffVo(v)
        if vo then 
            local go = self.LayoutGroup.transform:Find("LevelItem"..(checkNumber(vo.quality) - 1))
            self:FillBuff(go, v)
        end
    end
end

function UITalentMaterialLevelSelectionDialog:FillBuff(go, buffId)
    if not go or not buffId then
        return
    end

    local scr = CfUtils.GetLuaScr(go, UITalentMaterialLevelSelectionNode)
    if scr then
        scr:Refresh(buffId, self._curQuestId, function()
            if checkNumber(self._curChooseBuffId) ~= 0 then 
                local vo = QuestConfMgr:GetInstance():GetTalentBuffVo(self._curChooseBuffId)
                if vo then
                    local lastGo = self.LayoutGroup.transform:Find("LevelItem"..(checkNumber(vo.quality) - 1))
                    if lastGo then
                        local lastScr = CfUtils.GetLuaScr(lastGo, UITalentMaterialLevelSelectionNode)
                        if lastScr then
                            lastScr:FillSelect(false)
                        end
                    end
                end 
            end

            self._curChooseBuffId = buffId
            scr:FillSelect(true)
        end, function()
            talentQuestComponent:ChooseBuffIdReq(self._curQuestId, self._curChooseBuffId, function()
                local t = QuestConfMgr:GetInstance():GetTalentUpBuffDataByPlanId(talentQuestComponent:GetCurPlanId())
                self:OnBtnClose()
                --CS.Engine.UI.UIModule.OpenDialog({ id = Constants.UITypeIds.UIFightTeamChoose, parameters = {levelId = self._curQuestId, upBuffData = t}}, {
                --    {id = Constants.UITypeIds.UITalentMaterialDialog}
                --})
                KCookie.Set("TalentChooseBuffId", self._curChooseBuffId)
            end, function()
                self:OnBtnClose()
            end)
        end)
    end
end

